<?php
require_once __DIR__.'/includes/functions.php';require_role(['admin']);$pageTitle='Reports';
$totalBooks=(int)db()->query('SELECT COALESCE(SUM(total_quantity),0) FROM books WHERE is_active=1')->fetchColumn();$issued=(int)db()->query("SELECT COUNT(*) FROM issues WHERE status='issued'")->fetchColumn();$returned=(int)db()->query("SELECT COUNT(*) FROM issues WHERE status='returned'")->fetchColumn();$overdue=(int)db()->query("SELECT COUNT(*) FROM issues WHERE status='issued' AND due_date<CURDATE()")->fetchColumn();$fine=(float)db()->query('SELECT COALESCE(SUM(amount),0) FROM fines')->fetchColumn();$paid=(float)db()->query('SELECT COALESCE(SUM(paid_amount),0) FROM fines')->fetchColumn();$popular=db()->query('SELECT title,author,times_issued FROM books WHERE is_active=1 ORDER BY times_issued DESC,title LIMIT 10')->fetchAll();$monthly=db()->query("SELECT DATE_FORMAT(issue_date,'%Y-%m') AS month,COUNT(*) AS total FROM issues WHERE issue_date>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY month ORDER BY month")->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="mb-4"><p class="text-primary small text-uppercase fw-bold mb-1">Administration</p><h1 class="page-title mb-1">Library reports</h1><p class="muted mb-0">A snapshot of circulation and collection performance.</p></div><div class="row g-3 mb-4"><?php foreach([['Total copies',$totalBooks,'bi-book'],['Active loans',$issued,'bi-arrow-left-right'],['Returned loans',$returned,'bi-check-circle'],['Overdue now',$overdue,'bi-alarm'],['Fines recorded',money($fine),'bi-cash-stack'],['Outstanding',money(max(0,$fine-$paid)),'bi-wallet2']] as $x): ?><div class="col-6 col-md-4 col-xl-2"><div class="stat-card"><div class="stat-icon mb-3"><i class="bi <?=e($x[2])?>"></i></div><div class="stat-value" style="font-size:1.45rem"><?=e((string)$x[1])?></div><div class="muted small mt-1"><?=e($x[0])?></div></div></div><?php endforeach; ?></div><div class="row g-3"><div class="col-lg-7"><div class="surface p-4 h-100"><h2 class="h5 fw-bold mb-3">Most borrowed books</h2><?php $max=max(1,(int)($popular[0]['times_issued']??0));foreach($popular as $b): ?><div class="d-flex justify-content-between gap-3 small mb-2 mt-3"><span><?=e($b['title'])?> <span class="muted">· <?=e($b['author'])?></span></span><strong><?= (int)$b['times_issued']?></strong></div><div class="chart-bar"><span style="width:<?=round((int)$b['times_issued']/$max*100)?>%"></span></div><?php endforeach; ?><?php if(!$popular): ?><p class="muted">No books to report yet.</p><?php endif; ?></div></div><div class="col-lg-5"><div class="surface p-4 h-100"><h2 class="h5 fw-bold mb-3">Monthly issues</h2><?php if(!$monthly): ?><p class="muted">No issue activity in the last six months.</p><?php else:$mmax=max(1,max(array_column($monthly,'total')));foreach($monthly as $m): ?><div class="d-flex justify-content-between small mb-2 mt-3"><span><?=e($m['month'])?></span><strong><?=(int)$m['total']?> loans</strong></div><div class="chart-bar"><span style="width:<?=round($m['total']/$mmax*100)?>%"></span></div><?php endforeach;endif; ?><a class="btn btn-outline-primary mt-4" href="loans.php">Open circulation desk</a></div></div></div>
